export const fileDetailColumns = (columnsData) => {
  const data = columnsData.map(({
    expected,
    api_key: apiKey
  }) => ({
    key: apiKey,
    dataIndex: expected,
    title: expected,
    render: (data) => <span style={{ wordBreak: 'break-word' }}>{data}</span>
  }))
  return [
    ...data,
    {
      title: 'Row Status',
      dataIndex: 'row_status',
      key: 9,
      width: 150
    },
    {
      title: 'Errors',
      dataIndex: 'errors',
      key: 10,
      width: 200,
      render: (data) => <span style={{ wordBreak: 'break-word' }}>{data}</span>
    }
  ]
}
